      const edge = resolveImport(renderer.bindings[local]);
      if (edge.specifier !== shared.specifier || edge.local !== shared.structure.bindings[upstream]) return null;
    }
    const chalk = resolveImport(names.bGt);
    if (chalk.structure.digest !== '2fdd7ca5ded53c63977f6f7efb408920fd99b93e1fee3ce1f25a57d809c27aab'
      || chalk.local !== chalk.structure.bindings[187]) return null;
    const styles = resolveImport(names.MNr), normalizedStyles = resolveImport(names.LNr);
    if (styles.specifier !== normalizedStyles.specifier
      || cellDeclarationContract(styles.source, [styles.local, normalizedStyles.local]).digest !== '549f52003f118824c71b45c8abda724deb6e7c17848fc353a012e07c49f30e9e') return null;
    function verifyEdges(contract, expected) {
      if (contract.imports.length !== expected.length) return false;
      return contract.imports.every((edge, index) => {
        const text = dependencies.get(basename(edge.specifier));
        if (typeof text !== 'string') return false;
        const parsed = structuralModule(text);
        const [digest, binding] = expected[index];
        const exported = parsed.ast.body.flatMap(node => node.type === 'ExportNamedDeclaration' ? node.specifiers : [])
          .find(item => item.exported.name === edge.imported);
        return parsed.digest === digest && exported?.local.name === parsed.bindings[binding];
      });
    }
    if (!verifyEdges(cellDeclarationContract(styles.source, [styles.local, normalizedStyles.local]), [[chalk.structure.digest, 176]])) return null;
    const tabs = resolveImport(names.hht);
    const expanders = imports.filter(node => node.source.value === tabs.specifier).flatMap(node => node.specifiers)
      .filter(item => item.local.name !== names.hht).filter(item => {
        try {
          const edge = resolveImport(item.local.name);
          const contract = cellDeclarationContract(tabs.source, [tabs.local, edge.local]);
          return contract.digest === '714287168495299b3b5a5d0c9ee451730c3b2d8cd4817813a6319661ce152c46'
            && verifyEdges(contract, [...[0,5,12,6,14,10].map(index => ['ea528a66e176e8d0e965ba61400fe5c041c2e03ab480314d3bdc64c31a87f1f8', index]),
              [windows ? '3128c6dd72850c8e53097f5ff2d5cacbb841a6eff22da707f8e8e904fdabb7e3' : '1fd9187348c1e13e2407819e6ab3892ac64e1e3d313a3f3a460665d47317df66', 1]]);
        } catch { return false; }
      });
    if (expanders.length !== 1) return null;
    names.C8 = expanders[0].local.name;
    const ansiCandidates = imports.map(node => {
      const text = dependencies.get(basename(node.source.value));
      if (!text || !text.includes('Number.POSITIVE_INFINITY')) return null;
      const structure = structuralModule(text);
      return structure.digest === '5c710815d4d1b551b526147eacb70dcd92be27824e3e2e7ef6252df9eb1f911a'
        ? { source: text, structure, specifier: node.source.value } : null;
    }).filter(Boolean);
    if (ansiCandidates.length !== 1) return null;
    const ansi = ansiCandidates[0];
    const textCandidates = [];
    for (const [file, text] of dependencies) {
      if (!text.includes(shared.specifier) || !text.includes('.trimEnd()')) continue;
      const parsed = cellAst.parse(text, { ecmaVersion: 'latest', sourceType: 'module' });
      const functions = parsed.body.filter(node => node.type === 'FunctionDeclaration');
      const checks = functions.filter(node => { const body = text.slice(node.start,node.end); return body.includes('.trimEnd()') && body.includes('.indexOf('); });
      const segments = functions.filter(node => text.slice(node.start,node.end).includes(`${shared.local}(`));
      if (checks.length !== 1 || segments.length !== 1) continue;
      const contract = cellDeclarationContract(text, [checks[0].id.name, segments[0].id.name]);
      if (contract.digest !== '806962f28be74e895c24d42d325ff581238ccc482c57443c68d12e6a93f51733') continue;
      for (const [local, upstream] of [[3,5],[4,6],[5,0]]) {
        const edge = contract.imports.find(item => item.local === contract.bindings[local]);
        if (edge?.specifier !== shared.specifier || edge.imported !== shared.structure.bindings[upstream]) return null;
      }
      const branch = text.slice(checks[0].start,checks[0].end).match(/if\(![\w$]+\.test\([\w$]+\)\)return [\w$]+\([\w$]+\([\w$]+\)\);/);
      if (branch) textCandidates.push({ file, source: text, branch: branch[0] });
    }
    if (textCandidates.length !== 1) return null;
    const text = textCandidates[0];
    const anchors = [...source.matchAll(/let ([\w$]+)=([\w$]+)\(([\w$]+)\),([\w$]+)=([\w$]+)\.x2-([\w$]+)/g)]
      .filter(match => match[2] === names.Dc);
    if (anchors.length !== 1) return null;
    const [tabAnchor, out, sanitize, input, width, box, col] = anchors[0];
    const shape = roots.map(name => {
      const node = ast.body.find(node => node.id?.name === name);
      const declaration = source.slice(node.start, node.end);
      return { header: declaration.slice(0, declaration.indexOf('{') + 1), digest: hash(declaration) };
    });
    const line = ast.body.find(node => node.id?.name === names.xC);
    const [screen,, x, y, cells] = line.params.map(node => node.name);
    const call = line.body.body.at(-1)?.argument?.alternate;
    if (call?.type !== 'CallExpression') return null;
    const writeLineSource = source.slice(line.start,call.start) + `paintCells(${screen},${cells}.cells,${x},${y})` + source.slice(call.end,line.end);
    return { shape, names, writeLineSource, mappedWriteLine: true, tabAnchor,
      tabReplacement: `let ${out}=${sanitize}(${input});if(${out}.indexOf(String.fromCharCode(9))>=0){let clawgodTabOffset=((${col}%${names.hht})+${names.hht})%${names.hht};${out}=${names.C8}([" ".repeat(clawgodTabOffset)+${out}]).join("").slice(clawgodTabOffset)}let ${width}=${box}.x2-${col}`,
      dependency: { specifier: ansi.specifier, digest: hash(ansi.source), tokenizer: ansi.structure.bindings[115], normalizeStyles: ansi.structure.bindings[63] },
      shared: { specifier: shared.specifier, digest: hash(shared.source), factory: shared.local,
        text: text.file, textDigest: hash(text.source), textBranch: text.branch },
    };
  } catch { return null; }
}

const CELL_RENDERER_NAMES = Object.freeze([
  'clawgodCacheLimit', 'clawgodOsc8Prefix', 'clawgodSgr', 'clawgodAmbiguousNarrow',
  'clawgodSegmenter', 'clawgodGraphemes', 'clawgodCsiEnd', 'clawgodOscEnd',
  'sanitizeControlSequences', 'parseStyledText', 'packCell', 'unionDamage',
  'writeCell', 'paintCells', 'clawgodAnsiTokens', 'clawgodNormalizeStyles', 'clawgodMergeStyles',
]);

// Locates the closing brace of a declaration. The result is always checked
// against a frozen digest before anything is rewritten, so a mis-scan can only
// cause a rejected candidate, never a corrupted one.
export function findDeclarationEnd(source, start) {
  let depth = 0;
  let previous = '';
  for (let index = start; index < source.length; index++) {
    const char = source[index];
    const next = source[index + 1];
    if (char === '/' && next === '/') {
      index = source.indexOf('\n', index);
      if (index < 0) return -1;
      continue;
    }
    if (char === '/' && next === '*') {
      index = source.indexOf('*/', index);
      if (index < 0) return -1;
      index += 1;
      continue;
    }
    if (char === '"' || char === "'" || char === '`') {
      index = findStringEnd(source, index, char);
      if (index < 0) return -1;
      previous = 'value';
      continue;
    }
    if (char === '/' && startsExpression(previous)) {
      index = findRegexEnd(source, index);
      if (index < 0) return -1;
      previous = 'value';
      continue;
    }
    if (/[A-Za-z0-9_$]/.test(char)) {
      while (index + 1 < source.length && /[A-Za-z0-9_$]/.test(source[index + 1])) index += 1;
      previous = 'value';
      continue;
    }
    if (!/\s/.test(char)) {
      if (char === '{') depth += 1;
      else if (char === '}' && --depth === 0) return index;
      previous = char;
    }
  }
  return -1;
}

function findStringEnd(source, start, quote) {
  for (let index = start + 1; index < source.length; index++) {
    const char = source[index];
    if (char === '\\') {
      index += 1;
      continue;
    }
    if (char === quote) return index;
    if (quote === '`' && char === '$' && source[index + 1] === '{') {
      const end = findDeclarationEnd(source, index + 1);
      if (end < 0) return -1;
      index = end;
    }
  }
  return -1;
}

function findRegexEnd(source, start) {
  let inClass = false;
  for (let index = start + 1; index < source.length; index++) {
    const char = source[index];
    if (char === '\\') {
      index += 1;
      continue;
    }
    if (char === '\n') return -1;
    if (char === '[') inClass = true;
    else if (char === ']') inClass = false;
    else if (char === '/' && !inClass) return index;
  }
  return -1;
}

function startsExpression(previous) {
  return previous === '' || !/[)\]}\w$]/.test(previous);
}

/**
 * Rewrites a frozen private-runtime renderer into the public-Bun one.
 * Returns null when the module matches no frozen platform shape, so the caller
 * can refuse the candidate instead of installing a runtime that cannot start.
 * `shape` is a parameter so the guard rails around the rewrite can be
 * exercised offline; production callers always use the frozen table.
 */
export function adaptCellRenderer(source, shape, dependencies = new Map()) {
  const profiles = shape ? [{ ...CELL_PLATFORM_SHAPES[0], shape }] : CELL_PLATFORM_SHAPES;
  for (const profile of profiles) {
    const adapted = adaptCellRendererShape(source, profile, dependencies);
    if (adapted !== null) return adapted;
  }
  if (!shape && source.includes('stylePool;charPool;native=')) {
    const profile = localCellProfile(source, dependencies) ?? structuralCellProfile(source, dependencies);
    if (profile) return adaptCellRendererShape(source, profile, dependencies);
  }
  return null;
}

function adaptCellRendererShape(source, { shape, names, tabAnchor, tabReplacement, dependency, shared, writeLineSource = CELL_WRITE_LINE_SOURCE, mappedWriteLine = false, oscDeclaration = OSC8_DECLARATION }, dependencies) {
  if (shared) {
    const factory = dependencies.get(basename(shared.specifier));
    if (typeof factory !== 'string' || createHash('sha256').update(factory).digest('hex') !== shared.digest) return null;
    const imports = [...source.matchAll(/import\{([^}]*)\}from"([^"]+)";/g)]
      .filter(match => match[2] === shared.specifier);
    if (imports.length !== 1 || !imports[0][1].split(',').includes(shared.factory)
      || [...source.matchAll(new RegExp(`\\b${shared.factory.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'g'))].length !== 2) return null;
  }
  for (const name of CELL_RENDERER_NAMES) {
    if (source.includes(name)) return null;
  }
  let ansiImport = '';
  if (dependency) {
    // 2.1.285 把 ANSI 分词和样式合并拆到独立模块；冻结整个依赖，不能只信导出名。
    const ansi = dependencies.get(basename(dependency.specifier));
    if (typeof ansi !== 'string' || createHash('sha256').update(ansi).digest('hex') !== dependency.digest) return null;
    const imports = [...source.matchAll(/import\{[^}]*\}from"([^"]+)";/g)]
      .filter(match => match[1] === dependency.specifier);
    if (imports.length !== 1) return null;
    ansiImport = `import{${dependency.tokenizer} as clawgodAnsiTokens,${dependency.normalizeStyles} as clawgodNormalizeStyles}from${JSON.stringify(dependency.specifier)};\n`
      + 'function clawgodMergeStyles(styles,codes){return clawgodNormalizeStyles([...styles,...codes])}\n';
  } else if (!source.includes(oscDeclaration)) return null;
  for (const binding of CELL_SEGMENTER_BINDINGS) {
    const local = names[binding] ?? binding;
    const present = [...source.matchAll(/import\{([^}]*)\}from/g)].some((match) =>
      match[1].split(',').some(specifier => specifier.trim().split(/\s+as\s+/).at(-1) === local));
    if (!present) return null;
  }
  if (source.split(tabAnchor).length !== 2) return null;
  const spans = [];
  for (const { header, digest } of shape) {
    const start = source.indexOf(header);
    if (start < 0 || source.indexOf(header, start + header.length) >= 0) return null;
    const end = findDeclarationEnd(source, start + header.length - 1);
    if (end < 0) return null;
    if (createHash('sha256').update(source.slice(start, end + 1)).digest('hex') !== digest) return null;
    spans.push({ start, end: end + 1 });
  }
  const replacements = [
    [spans[0], CELL_RENDERER_SOURCE],
    [spans[1], CELL_LINE_CELLS_SOURCE],
    [spans[2], CELL_SET_CELL_SOURCE],
    [spans[3], writeLineSource],
  ].sort((first, second) => second[0].start - first[0].start);
  let adapted = source;
  for (const [span, text] of replacements) {
    // 注入模板中的这些短名只作为标识符出现；单次替换避免 Cx→Rx→Mx 连锁改名。
    const mapped = mappedWriteLine && span === spans[3] ? text
      : text.replace(/\b(?:Ns|Dd|Cx|xC|cmr|Kf|Dc|bn|wo|Xf|jn|Rx|xx|hht|C8|MNr|LNr|bGt)\b/g, name => names[name] ?? name);
    adapted = adapted.slice(0, span.start) + mapped + adapted.slice(span.end);
  }
  return ansiImport + adapted.replace(tabAnchor, tabReplacement);
}

// 2.1.269+ 渲染器硬依赖私有 Bun.ant.CellSegmenter。公开 Bun 给不了，所以在
// 改写候选、发布到现有安装之前换成等价的 JS 实现；形态不认识就整体拒绝，
// 免得写出一个 --version 能过、交互界面却起不来的运行时。
const CELL_SEGMENTER_REFERENCE = /\bnew\s+Bun\s*\.\s*ant\s*\.\s*CellSegmenter\s*\(/;

function installPublicCellRenderer(modulePaths) {
  if (typeof globalThis.Bun?.ant?.CellSegmenter === 'function') return;
  const targets = [];
  const dependencies = new Map();
  for (const path of modulePaths) {
    const source = readFileSync(path, 'utf8');
    dependencies.set(basename(path), source);
    if (CELL_SEGMENTER_REFERENCE.test(source)) targets.push({ path, source });
  }
  if (targets.length === 0) return;
  if (targets.length > 1) {
    throw new Error(`多个分块都依赖私有 Bun.ant.CellSegmenter，形态无法确认；已拒绝安装（${targets.length} 个）。`);
  }
  let sharedProfile = CELL_PLATFORM_SHAPES.find(profile => profile.shared
    && basename(profile.shared.specifier) === basename(targets[0].path));
  if (!sharedProfile) {
    const profiles = [...dependencies.values()].filter(source => source.includes('stylePool;charPool;native='))
      .map(source => localCellProfile(source, dependencies) ?? structuralCellProfile(source, dependencies)).filter(Boolean)
      .filter(profile => basename(profile.shared.specifier) === basename(targets[0].path));
    if (profiles.length === 1) sharedProfile = profiles[0];
  }
  if (sharedProfile) {
    const { shared } = sharedProfile;
    const renderer = modulePaths.map(path => ({ path, source: dependencies.get(basename(path)) }))
      .filter(({ source }) => adaptCellRendererShape(source, sharedProfile, dependencies) !== null);
    const text = dependencies.get(shared.text);
    if (renderer.length !== 1 || typeof text !== 'string'
      || createHash('sha256').update(text).digest('hex') !== shared.textDigest) {
      throw new Error('共享 CellSegmenter 的渲染器或名称校验分块发生漂移；已拒绝安装。');
    }
    const factorySource = targets[0].source;
    const factoryHeader = `function ${shared.factory}(`;
    const factoryStart = factorySource.indexOf(factoryHeader);
    const factoryEnd = findDeclarationEnd(factorySource, factorySource.indexOf('{', factoryStart));
    const exports = factorySource.match(/export\{([^}]+)\};/)[1].split(',');
    for (const path of modulePaths) {
      const source = dependencies.get(basename(path));
      const sharedFile = basename(shared.specifier);
      if (!source.includes(sharedFile)) continue;
      const imports = [...source.matchAll(/import(?:\{([^}]*)\}from)?"([^"]+)";/g)]
        .filter(match => basename(match[2]) === sharedFile);
      const references = source.split(sharedFile).length - 1;
      if (imports.length !== references || imports.some(match => match[1]?.split(',').some(binding =>
        !exports.includes(binding) || binding === shared.factory
        && path !== renderer[0].path && basename(path) !== shared.text))) {
        throw new Error('共享 CellSegmenter 出现未知调用者；已拒绝安装。');
      }
    }
    // ponytail: 非 ASCII 技能名沿用上游保守子序列校验，可能多拒绝名称；
    // 原生文本 ABI 可公开验证等价后再恢复精确判断，不能为兼容跳过防冒充。
    const updates = new Map([
      [renderer[0].path, adaptCellRendererShape(renderer[0].source, sharedProfile, dependencies)],
      [modulePaths.find(path => basename(path) === shared.text), text.replace(shared.textBranch, '')],
      [targets[0].path, factorySource.slice(0, factoryStart)
        + `function ${shared.factory}(){throw Error("ClawGod 已替换私有 CellSegmenter；不支持新增的原生调用路径。")}`
        + factorySource.slice(factoryEnd + 1)],
    ]);
    for (const [path, source] of updates) writeFileSync(path, source);
    console.log('已用公开 Bun 字符格渲染器替换共享私有实现，并保留技能名称防冒充校验。');
    return;
  }
  const { path, source } = targets[0];
  const adapted = adaptCellRenderer(source, undefined, dependencies);
  if (adapted === null) {
    throw new Error('此 Claude Code 依赖私有 Bun.ant.CellSegmenter，且渲染器形态未被 ClawGod 识别；'
      + '已拒绝安装，避免产生无法进入交互界面的运行时。请用 --version 安装受支持的版本。');
  }
  writeFileSync(path, adapted);
  console.log(`已用公开 Bun 字符格渲染器替换私有实现: ${path.slice(here.length + 1)}`);
}

function processCandidate() {
  const chunksDir = join(here, 'chunks');
  const split = existsSync(chunksDir);
  const chunkPaths = split
    ? readdirSync(chunksDir).filter((name) => name.endsWith('.js')).map((name) => join(chunksDir, name))
    : [];

  installPublicCellRenderer([src, ...chunkPaths]);

  if (split) {
    // ── v2.1.245+ code-split format: ESM entry + chunk graph ──────────
    // The entry point is a thin dispatcher of `import ... from "/$bunfs/root/
    // chunk-*.js"` statements. Rewrite its specifiers (chunks live one level
    // down) and rewrite every chunk (sibling specifiers) in place.
    let entry = readFileSync(src, 'utf8');
    entry = rewrite(entry, { chunkPrefix: './chunks/' });
    writeFileSync(dst, entry);
    unlinkSync(src);

    for (const path of chunkPaths) {
      const code = rewrite(readFileSync(path, 'utf8'), { chunkPrefix: './' });
      writeFileSync(path, code);
    }
    console.log(`cli.original.cjs: ${entry.length} bytes (code-split, chunks rewritten)`);
  } else {
    // ── legacy monolithic CJS bundle ──────────────────────────────────
    let code = readFileSync(src, 'utf8');

    // Strip leading @bun pragma comments (e.g. "// @bun @bytecode @bun-cjs\n")
    // Bun requires the file to start directly with "(function" to recognize
    // the CommonJS wrapper; any preceding comment breaks that detection.
    code = code.replace(/^(?:\/\/[^\n]*\n)+/, '');

    // (1) bunfs .node module paths → runtime vendor lookup
    code = code.replace(
      /require\(['"](\/\$bunfs\/root\/([\w-]+)\.node)['"]\)/g,
      (m, _full, name) =>
        `require(require('path').join(__dirname,'vendor',${JSON.stringify(name)},\`\${process.arch==='arm64'?'arm64':'x64'}-\${process.platform==='darwin'?'darwin':process.platform==='linux'?'linux':'win32'}\`,${JSON.stringify(name + '.node')}))`,
    );

    // (2) build-time fileURLToPath() leaks → use cli.cjs's own __filename
    code = code.replace(
      /[\w$]+\.fileURLToPath\("file:\/\/\/home\/runner\/work\/claude-cli-internal\/claude-cli-internal\/[^"]*"\)/g,
      () => '__filename',
    );

    // (3) make the outer (function(...){...}) actually run
    code = code.replace(/\}\)\s*$/, '})(exports, require, module, __filename, __dirname)');

    writeFileSync(dst, code);
    unlinkSync(src);
    console.log(`cli.original.cjs: ${code.length} bytes (monolithic)`);
  }
}

if (import.meta.main) processCandidate();
POSTPROC_EOF
cp "$CLAWGOD_DIR/post-process.mjs" "$RUNTIME_CANDIDATE_DIR/post-process.mjs"
if postprocess_output=$("$BUN_BIN" "$RUNTIME_CANDIDATE_DIR/post-process.mjs" "$CLAWGOD_DIR" 2>&1); then
  printf '%s\n' "$postprocess_output"
else
  printf '%s\n' "$postprocess_output" >&2
  err "Post-process failed"
  exit 1
fi
[ -f "$RUNTIME_CANDIDATE_DIR/cli.original.cjs" ] || { err "Post-process failed"; exit 1; }
mv "$RUNTIME_CANDIDATE_DIR/cli.original.cjs" "$CLAWGOD_DIR/cli.original.cjs"
# Code-split chunk graph (v2.1.245+): every non-entry js module extracted by
# extract-natives.mjs into candidate/chunks/. Move it into place alongside
# cli.original.cjs so the patcher and runtime can resolve the rewritten
# relative import specifiers.
rm -rf "$CLAWGOD_DIR/chunks" "$CLAWGOD_DIR/assets"
if [ -d "$RUNTIME_CANDIDATE_DIR/chunks" ]; then
  mv "$RUNTIME_CANDIDATE_DIR/chunks" "$CLAWGOD_DIR/chunks"
fi
# Design canvas editor payload (loader=file asset from the binary) — see
# wrapper.cjs CLAWGOD_DESIGN_PAYLOAD export.
if [ -d "$RUNTIME_CANDIDATE_DIR/assets" ]; then
  rm -rf "$CLAWGOD_DIR/assets"
  mv "$RUNTIME_CANDIDATE_DIR/assets" "$CLAWGOD_DIR/assets"
fi
RUNTIME_HAS_CANDIDATE_VENDOR=1

if [ "$NO_UPGRADE" = "1" ] && [ "$NATIVE_BIN_LABEL" != "$CURRENT_SOURCE_VERSION" ]; then
  err "Recovered source version does not match installed version $CURRENT_SOURCE_VERSION"
  exit 1
fi
"$BUN_BIN" "$RUNTIME_STATE_HELPER" clean-save "$CLAWGOD_DIR" "$NATIVE_BIN_LABEL"
# Stamp the source version so the wrapper can detect drift on next launch
echo "$NATIVE_BIN_LABEL" > "$CLAWGOD_DIR/.source-version"

# If we pulled the binary from npm into a tmpdir, clean it up now —
# extraction is done, drift detection only consults ~/.local/share/claude/versions/.
if [ -n "$NATIVE_BIN_TMPDIR" ]; then
  rm -rf "$NATIVE_BIN_TMPDIR"
fi

info "cli.original.cjs ready ($NATIVE_BIN_LABEL)"

fi  # end --no-upgrade skip

# ─── Write re-patch helper (used by wrapper on version drift) ─────────

cat > "$CLAWGOD_DIR/repatch.mjs" << 'REPATCH_EOF'
#!/usr/bin/env bun
// Re-extract + post-process + patch the user's currently-installed native binary.
import { spawnSync } from 'node:child_process';
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { publishVendorTransaction, validateRuntime } from './vendor-transaction.mjs';
import state from './runtime-state.cjs';

const here = dirname(fileURLToPath(import.meta.url));
const nativeBin = process.argv[2];
if (!nativeBin || !existsSync(nativeBin) || !/^\d+\.\d+\.\d+(?:[-+][A-Za-z0-9.-]+)?$/.test(basename(nativeBin))) {
  console.error('repatch: native binary path must exist and its basename must identify the exact source version');
  process.exit(1);
}
const version = basename(nativeBin);
const runtime = process.execPath;
function run(label, args) {
  const result = spawnSync(runtime, args, { cwd: here, stdio: 'inherit' });
  if (result.error || result.status !== 0) throw new Error(`repatch: ${label} failed (${result.error?.message || `exit ${result.status}`})`);
}
const transactionDir = mkdtempSync(join(here, '.runtime-rollback.'));
const candidateDir = join(transactionDir, 'candidate');
const candidateVendor = join(candidateDir, 'vendor');
let vendorPublishAttempted = false;
let snapshotted = false;
try {
  state.snapshot(here, transactionDir);
  snapshotted = true;
  let cleanReady = false;
  if (existsSync(join(here, '.source-version')) && readFileSync(join(here, '.source-version'), 'utf8').trim() === version) {
    try { state.restoreClean(here, version); cleanReady = true; } catch {}
  }
  if (!cleanReady) {
    mkdirSync(candidateDir);
    run('extract', [join(here, 'extract-natives.mjs'), nativeBin, candidateDir]);
    const candidatePostProc = join(candidateDir, 'post-process.mjs');
    copyFileSync(join(here, 'post-process.mjs'), candidatePostProc);
    run('post-process', [candidatePostProc, here]);
    rmSync(join(here, 'cli.original.cjs'), { force: true });
    renameSync(join(candidateDir, 'cli.original.cjs'), join(here, 'cli.original.cjs'));
    for (const name of ['chunks', 'assets']) {
      rmSync(join(here, name), { recursive: true, force: true });
      if (existsSync(join(candidateDir, name))) renameSync(join(candidateDir, name), join(here, name));
    }
    state.saveClean(here, version);
  }
  const patchArgs = [join(here, 'patch.mjs'), '--enhancements-file', join(here, 'enhancements.json')];
  if (process.env.CLAWGOD_TOLERATE_STALE === '1' || process.argv.includes('--tolerate-stale')) patchArgs.push('--tolerate-stale');
  run('patcher', patchArgs);
  writeFileSync(join(here, '.source-version'), version + '\n');
  if (!cleanReady) {
    vendorPublishAttempted = true;
    publishVendorTransaction({
      liveVendor: join(here, 'vendor'), candidateVendor, transactionDir,
      validatePublished: () => validateRuntime(runtime, join(here, 'cli.cjs')),
    });
  } else {
    validateRuntime(runtime, join(here, 'cli.cjs'));
  }
  rmSync(transactionDir, { recursive: true, force: true });
  console.log(`[clawgod] re-patched to ${version}`);
} catch (error) {
  const vendorRestored = !vendorPublishAttempted || error?.rollbackComplete === true;
  if (vendorRestored) {
    try {
      if (snapshotted) state.restore(here, transactionDir);
      if (!vendorPublishAttempted || error?.cleanupSafe !== false) rmSync(transactionDir, { recursive: true, force: true });
      else console.error(`repatch: prior CLI restored; untrusted transaction data retained at ${transactionDir}`);
    } catch (rollbackError) {
      console.error(`repatch: runtime rollback failed; recovery data retained at ${transactionDir}: ${rollbackError.message}`);
    }
  } else {
    console.error(`repatch: vendor rollback conflict; prior CLI was not restored; recovery data retained at ${transactionDir}`);
  }
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
}
