    const homeDir = dirname2(configDirectory);
    if (configFile !== enhancementConfigPath(homeDir) || configFile !== join2(homeDir, ".clawgod", ENHANCEMENT_CONFIG_FILENAME)) {
      throw new Error("--enhancements-file must name the canonical enhancements.json path");
    }
    stored = await readEnhancementConfig({ homeDir, manifest: enhancementManifest });
  }
  const selection = resolveEnhancementSelection({ stored }, enhancementManifest);
  const { patches, customPatches } = createPatchSelection(selection.enabled);
  if (revert) {
    if (!restoreBundle(rootDir)) {
      console.error("\u274C No backup found");
      process.exit(1);
    }
    console.log("\u2705 Reverted from backup");
    return;
  }
  if (!existsSync(target)) {
    console.error("\u274C Target not found:", target);
    process.exit(1);
  }
  const modules = readBundle(rootDir);
  const hasChunks = modules.length > 1;
  let code = concatModules(modules);
  const originalSize = modules.reduce((sum, module) => sum + module.code.length, 0);
  const { version } = inspectPatcherSource(code);
  console.log(`
${"\u2550".repeat(55)}`);
  console.log("  ClawGod Plus (universal)");
  console.log(`  Target: cli.original.cjs (v${version})${hasChunks ? ` + ${modules.length - 1} chunks` : ""}`);
  console.log(`  Mode: ${dryRun ? "DRY RUN" : verify ? "VERIFY" : "APPLY"}`);
  console.log(`  Enhancements: ${selection.enabled.length} enabled, ${enhancementManifest.length - selection.enabled.length} disabled`);
  console.log(`${"\u2550".repeat(55)}
`);
  let applied = 0;
  let skipped = 0;
  let failed = 0;
  let warnings = 0;
  const tolerated = [];
  const stale = (name, detail) => {
    console.log(`  ${tolerateStale ? "WARNING" : "FAILED"} ${name} \u2014 ${detail}${tolerateStale ? " (tolerated)" : ""}`);
    if (tolerateStale)
      tolerated.push(name);
    else
      failed++;
  };
  try {
    const semanticDescriptors = [...patches, ...customPatches].filter((descriptor) => descriptor.semanticId);
    const semantic = applySemanticPatches(code, semanticDescriptors, { dryRun, verify });
    code = semantic.code;
    for (const descriptor of semanticDescriptors) {
      const result = semantic.results.get(descriptor);
      if (result.status === "stale")
        stale(descriptor.name, result.detail);
      else if (result.status === "failed") {
        console.log(`  FAILED ${descriptor.name} \u2014 ${result.detail}`);
        failed++;
      } else if (result.status === "applied" || result.status === "already") {
        console.log(`  OK ${descriptor.name} (${result.count ?? "already applied"}${result.count ? " replacements" : ""})`);
        applied++;
      } else
        skipped++;
    }
  } catch (error) {
    console.error(`AST scan/rewrite failed: ${error.message}. Source files were not changed.`);
    process.exit(1);
  }
  for (const patch of patches.filter((descriptor) => !descriptor.semanticId)) {
    const matches = [...code.matchAll(patch.pattern)];
    let relevant = matches;
    if (patch.validate) {
      relevant = matches.filter((match) => patch.validate(match[0], code));
    }
    if (patch.selectIndex !== undefined) {
      relevant = relevant.length > patch.selectIndex ? [relevant[patch.selectIndex]] : [];
    }
    if (patch.unique && relevant.length > 1) {
      console.log(`  \u26A0\uFE0F  ${patch.name} \u2014 ${relevant.length} matches, skipping (need 1)`);
      failed++;
      continue;
    }
    if (relevant.length === 0) {
      if (patch.knownShape?.test(code)) {
        stale(patch.name, "known resolver shape did not match exactly");
        continue;
      }
      if (patch.appliedMarker !== undefined && (patch.appliedMarker instanceof RegExp ? patch.appliedMarker.test(code) : code.includes(patch.appliedMarker))) {
        console.log(`  \u2705 ${patch.name} (already applied, marker present)`);
        applied++;
        continue;
      }
      if (patch.optional) {
        skipped++;
        continue;
      }
      if (patch.sentinel !== undefined) {
        const sentinels = Array.isArray(patch.sentinel) ? patch.sentinel : [patch.sentinel];
        const stillPresent = sentinels.filter((sentinel) => code.includes(sentinel));
        if (stillPresent.length > 0) {
          stale(patch.name, `regex stale, sentinel still in source: ${stillPresent.map((sentinel) => JSON.stringify(sentinel)).join(", ")}`);
          continue;
        }
        console.log(`  \u2705 ${patch.name} (already applied, sentinel absent)`);
        applied++;
        continue;
      }
      skipped++;
      continue;
    }
    if (verify) {
      skipped++;
      continue;
    }
    let count = 0;
    for (const match of relevant) {
      const replacement = patch.replacer(match[0], ...match.slice(1));
      if (replacement !== match[0]) {
        if (!dryRun)
          code = code.replace(match[0], () => replacement);
        count++;
      }
    }
    if (count > 0) {
      console.log(`  \u2705 ${patch.name} (${count} replacement${count > 1 ? "s" : ""})`);
      applied++;
    } else {
      skipped++;
    }
  }
  for (const descriptor of customPatches.filter((descriptor) => !descriptor.semanticId)) {
    const result = await descriptor.apply(code, { dryRun, verify, rootDir });
    if (result.status === "applied") {
      if (!dryRun)
        code = result.code;
      console.log(`  \u2705 ${descriptor.name} (${result.count} replacement${result.count > 1 ? "s" : ""})`);
      applied++;
      for (const warning of result.warnings ?? []) {
        console.log(`  \u26A0\uFE0F  ${descriptor.name}: ${warning} \u2014 pattern not found in this version`);
        warnings++;
      }
    } else if (result.status === "verify") {
      skipped++;
    } else if (result.status === "already") {
      console.log(`  \u2705 ${descriptor.name} (${result.detail})`);
      applied++;
    } else if (result.status === "skipped") {
      skipped++;
    } else if (result.status === "stale") {
      stale(descriptor.name, result.detail);
    } else {
      console.log(`  \u274C ${descriptor.name} \u2014 ${result.detail}`);
      failed++;
    }
  }
  console.log(`
${"\u2500".repeat(55)}`);
  if (tolerated.length)
    console.log(`  Tolerated (skipped, upstream behavior kept): ${tolerated.join("; ")}`);
  console.log(`  Result: ${applied} applied, ${skipped} skipped, ${failed} failed${warnings > 0 ? `, ${warnings} warning${warnings > 1 ? "s" : ""}` : ""}`);
  if (failed === 0 && !dryRun && !verify && applied > 0) {
    backupBundle(rootDir, modules);
    const resultModules = splitModules(code);
    if (resultModules.length !== modules.length) {
      console.error(`  \u274C Bundle split mismatch: ${resultModules.length} vs ${modules.length} modules`);
      process.exit(1);
    }
    for (let i = 0;i < modules.length; i++)
      modules[i].code = resultModules[i];
    writeBundle(rootDir, modules);
    const difference = resultModules.reduce((sum, module) => sum + module.length, 0) - originalSize;
    console.log(`  \uD83D\uDCDD Written: cli.original.cjs${hasChunks ? ` + ${modules.length - 1} chunks` : ""} (${difference >= 0 ? "+" : ""}${difference} bytes)`);
  }
  console.log(`${"\u2550".repeat(55)}
`);
  if (failed > 0)
    process.exit(allowCompatibilityFallback ? PATCH_COMPATIBILITY_EXIT_CODE : 1);
}
await runPatcher({
  rootDir: import.meta.main ? DEFAULT_ROOT : dirname2(process.argv[1] || fileURLToPath(import.meta.url))
});
export {
  PATCH_COMPATIBILITY_EXIT_CODE,
  runPatcher
};
PATCHER_EOF
info "Patcher created (patch.mjs)"

# ─── Apply patches ─────────────────────────────────────

dim "Applying patches ..."
patch_args=(--enhancements-file "$CLAWGOD_DIR/enhancements.json")
if [ "$TOLERATE_STALE" = "1" ]; then patch_args+=(--tolerate-stale); fi
patch_fallback_authorized=0
if [ "${CLAWGOD_UPDATE_PATCH_FAIL_OPEN:-}" = "1" ] \
  && [ "$NO_UPGRADE" != "1" ] \
  && [ "$RUNTIME_HAD_TARGET" = "1" ]; then
  patch_args+=(--allow-compatibility-fallback)
  patch_fallback_authorized=1
fi
patch_status=0
patch_output=$("$BUN_BIN" "$CLAWGOD_DIR/patch.mjs" "${patch_args[@]}" 2>&1) || patch_status=$?
while IFS= read -r line; do echo "  $line"; done <<< "$patch_output"
patch_fallback_active=0
if [ "$patch_status" -eq 0 ]; then
  "$BUN_BIN" "$CLAWGOD_DIR/patch-fallback.cjs" clear "$CLAWGOD_DIR"
elif [ "$patch_status" -eq 42 ] && [ "$patch_fallback_authorized" = "1" ]; then
  "$BUN_BIN" "$CLAWGOD_DIR/patch-fallback.cjs" write "$CLAWGOD_DIR" "$NATIVE_BIN_LABEL" "$CLAWGOD_SELF_VERSION"
  warn "PATCH COMPATIBILITY FALLBACK: Claude Code will run without bundle enhancements."
  warn "Run 'claude update' after ClawGod supports this Claude Code release."
  patch_fallback_active=1
else
  err "Mandatory patching failed; installation stopped before launcher replacement."
  exit "$patch_status"
fi
if [ "$patch_fallback_active" != "1" ]; then
  run_claude_code_chrome_fix
fi
commit_runtime_transaction

# ─── Create default configs ───────────────────────────

if [ ! -f "$CLAWGOD_DIR/features.json" ]; then
  cat > "$CLAWGOD_DIR/features.json" << 'FEATURES_EOF'
{
  "tengu_harbor": true,
  "tengu_session_memory": true,
  "tengu_amber_flint": true,
  "tengu_auto_background_agents": true,
  "tengu_destructive_command_warning": true,
  "tengu_immediate_model_command": true,
  "tengu_desktop_upsell": false,
  "tengu_ethereal_nova": true,
  "tengu_omelette_fouet": true,
  "tengu_slate_quill": true,
  "tengu_malort_pedway": {"enabled": true},
  "tengu_amber_quartz_disabled": false,
  "tengu_prompt_cache_1h_config": {"allowlist": ["*"]},
  "tengu_amber_redwood3": "enabled"
}
FEATURES_EOF
  info "Default features.json created"
fi

# ─── Lean mode: optimize ~/.claude/settings.json ─────
# Three levels: off (default) / on / max
# State persisted via .lean-disabled and .lean-max flag files.
# Installer respects existing state on updates — never overwrites user choice.

LEAN_OFF_FLAG="$CLAWGOD_DIR/.lean-disabled"
LEAN_MAX_FLAG="$CLAWGOD_DIR/.lean-max"

# Default to lean-off: if no lean flag files exist and user didn't explicitly
# request lean-on or lean-max, create the .lean-disabled flag so lean stays off.
if [ ! -f "$LEAN_OFF_FLAG" ] && [ ! -f "$LEAN_MAX_FLAG" ] && [ "$LEAN_ON" != "1" ] && [ "$LEAN_MAX" != "1" ]; then
  touch "$LEAN_OFF_FLAG"
fi

# Handle explicit toggle from CLI (--lean-off / --lean-on / --lean-max)
if [ "$LEAN_OFF" = "1" ]; then
  touch "$LEAN_OFF_FLAG"; rm -f "$LEAN_MAX_FLAG"
  CLAUDE_SETTINGS="$HOME/.claude/settings.json"
  if [ -f "$CLAUDE_SETTINGS" ]; then
    "$BUN_BIN" -e '
const fs=require("fs"),p=process.argv[1];
const allDeny=new Set(["DesignSync","NotebookEdit","PushNotification","RemoteTrigger","CronCreate","CronDelete","CronList","EnterPlanMode","ExitPlanMode","SendMessage","ScheduleWakeup","AskUserQuestion","ReportFindings"]);
const allFlags=["disableWorkflows","disableRemoteControl","disableClaudeAiConnectors","disableArtifact","disableBundledSkills"];
let s={};try{s=JSON.parse(fs.readFileSync(p,"utf8"))}catch{process.exit(0)}
for(const k of allFlags)delete s[k];
if(Array.isArray(s.permissions?.deny))s.permissions.deny=s.permissions.deny.filter(t=>!allDeny.has(t));
fs.writeFileSync(p,JSON.stringify(s,null,2)+"\n");
' "$CLAUDE_SETTINGS" 2>/dev/null
  fi
  info "Lean mode disabled (all tools restored)"
elif [ "$LEAN_ON" = "1" ]; then
  rm -f "$LEAN_OFF_FLAG" "$LEAN_MAX_FLAG"
elif [ "$LEAN_MAX" = "1" ]; then
  rm -f "$LEAN_OFF_FLAG"; touch "$LEAN_MAX_FLAG"
fi

if [ ! -f "$LEAN_OFF_FLAG" ]; then
  CLAUDE_SETTINGS_DIR="$HOME/.claude"
  CLAUDE_SETTINGS="$CLAUDE_SETTINGS_DIR/settings.json"
  mkdir -p "$CLAUDE_SETTINGS_DIR"
  LEAN_IS_MAX="false"
  [ -f "$LEAN_MAX_FLAG" ] && LEAN_IS_MAX="true"

  "$BUN_BIN" -e '
const fs = require("fs");
const settingsPath = process.argv[1];
const isMax = process.argv[2]?.toLowerCase() === "true";
const baseDeny = ["DesignSync","NotebookEdit","PushNotification","RemoteTrigger","CronCreate","CronDelete","CronList"];
const maxDeny = ["EnterPlanMode","ExitPlanMode","SendMessage","ScheduleWakeup","AskUserQuestion","ReportFindings"];
const baseFlags = ["disableWorkflows","disableClaudeAiConnectors","disableArtifact"];
const maxFlags = ["disableBundledSkills","disableRemoteControl"];
const deny = isMax ? [...baseDeny, ...maxDeny] : baseDeny;
const flags = isMax ? [...baseFlags, ...maxFlags] : baseFlags;
let s = {};
try { s = JSON.parse(fs.readFileSync(settingsPath, "utf8")); } catch {}
let changed = false;
// Migrate old Lean defaults and remove max-only settings when switching to on.
if (!isMax) {
  for (const k of maxFlags) { if (k in s) { delete s[k]; changed = true; } }
  if (Array.isArray(s.permissions?.deny)) {
    const before = s.permissions.deny.length;
    s.permissions.deny = s.permissions.deny.filter(t => !maxDeny.includes(t));
    if (s.permissions.deny.length !== before) changed = true;
  }
}
for (const k of flags) { if (!(k in s)) { s[k] = true; changed = true; } }
if (!s.permissions) s.permissions = {};
if (!Array.isArray(s.permissions.deny)) s.permissions.deny = [];
const ex = new Set(s.permissions.deny);
for (const t of deny) { if (!ex.has(t)) { s.permissions.deny.push(t); changed = true; } }
if (changed) fs.writeFileSync(settingsPath, JSON.stringify(s, null, 2) + "\n");
' "$CLAUDE_SETTINGS" "$LEAN_IS_MAX" 2>/dev/null

  if [ -f "$LEAN_MAX_FLAG" ]; then
    info "Lean settings applied: max (~/.claude/settings.json)"
  else
    info "Lean settings applied: on (~/.claude/settings.json)"
  fi
else
  dim "Lean mode disabled (claude --lean-on to re-enable)"
fi

# ─── Replace claude command ───────────────────────────

# Detect where claude is actually installed (supports native, npm, pnpm, yarn).
# `command -v` is a POSIX builtin (works even on minimal images that no
# longer ship `which`); `|| true` keeps a clean miss from tripping
# `set -e` via the assignment's exit status under bash 5+.
CLAUDE_BIN=$(command -v claude 2>/dev/null || true)
if [ -n "$CLAUDE_BIN" ] && is_unstable_claude_path "$CLAUDE_BIN"; then
  dim "Ignoring temporary Claude shim at $CLAUDE_BIN"
  CLAUDE_BIN="$BIN_DIR/claude"
elif [ -z "$CLAUDE_BIN" ]; then
  # No claude in PATH — use default location
  CLAUDE_BIN="$BIN_DIR/claude"
  dim "No existing claude found, installing to $BIN_DIR"
fi
CLAUDE_DIR=$(dirname "$CLAUDE_BIN")

# ─── Download clawgod-import binary ─────────────────────
IMPORT_BIN="$CLAWGOD_DIR/clawgod-import"
if [ ! -x "$IMPORT_BIN" ]; then
  IMPORT_ARCH="$(uname -m)"
  IMPORT_OS="$(uname -s | tr '[:upper:]' '[:lower:]')"
  case "$IMPORT_ARCH" in
    x86_64|amd64) IMPORT_ARCH="x64" ;;
    aarch64|arm64) IMPORT_ARCH="arm64" ;;
  esac
  case "$IMPORT_OS" in
    darwin) IMPORT_SUFFIX="darwin-$IMPORT_ARCH" ;;
    linux)  IMPORT_SUFFIX="linux-$IMPORT_ARCH" ;;
    *)      IMPORT_SUFFIX="" ;;
  esac
  if [ -n "$IMPORT_SUFFIX" ]; then
    IMPORT_URL="https://github.com/0Chencc/clawgod/releases/latest/download/clawgod-import-$IMPORT_SUFFIX"
    if "$BUN_BIN" "$CLAWGOD_DIR/fetch-file.mjs" "$IMPORT_URL" "$IMPORT_BIN" 2>/dev/null; then
      chmod +x "$IMPORT_BIN"
      info "Provider import tool installed (clawgod-import)"
    else
      dim "Provider import tool not yet available (build pending)"
    fi
  fi
fi

LAUNCHER_CONTENT="#!/bin/bash
# clawgod launcher
# CLAWGOD_LAUNCHER_V1
CLAWGOD_CLI=\"$CLAWGOD_DIR/cli.cjs\"
CLAWGOD_IMPORT=\"$CLAWGOD_DIR/clawgod-import\"
BUN_BIN=\"$BUN_BIN\"
# Route 'import' subcommand to clawgod-import binary
if [ \"\$1\" = \"import\" ]; then
  shift
  if [ -x \"\$CLAWGOD_IMPORT\" ]; then
    exec \"\$CLAWGOD_IMPORT\" \"\$@\"
  else
    echo \"clawgod: import tool not installed. Reinstall clawgod to get it.\" >&2
    exit 127
  fi
fi
if [ ! -f \"\$CLAWGOD_CLI\" ]; then
  echo \"clawgod: installation at $CLAWGOD_DIR is missing (cli.cjs not found)\" >&2
  echo \"clawgod: reinstall via  curl -fsSL https://github.com/A6083450/clawgod-plus/releases/latest/download/install.sh | bash\" >&2
  echo \"clawgod: or remove this launcher:  rm \\\"\$0\\\"\" >&2
  exit 127
fi
if [ ! -x \"\$BUN_BIN\" ]; then
  if command -v bun >/dev/null 2>&1; then BUN_BIN=\"\$(command -v bun)\"; fi
fi
if [ ! -x \"\$BUN_BIN\" ]; then
  echo \"clawgod: bun runtime not found at \$BUN_BIN\" >&2
  echo \"clawgod: install bun  curl -fsSL https://bun.sh/install | bash\" >&2
  exit 127
fi
export CLAUDE_CODE_EXECPATH=\"$CLAUDE_BIN.orig\"
export HERDR_AGENT=\"\${HERDR_AGENT-claude}\"
if [ \"\${1:-}\" = \"agents\" ] && [ \"\${CLAWGOD_NO_AUTO_CHROME:-}\" != \"1\" ]; then
  exec \"\$BUN_BIN\" \"\$CLAWGOD_CLI\" --chrome \"\$@\"
fi
CLAWGOD_AUTO_CHROME=1
if [ \"\${CLAWGOD_NO_AUTO_CHROME:-}\" = \"1\" ]; then
  CLAWGOD_AUTO_CHROME=0
fi
for arg in \"\$@\"; do
  case \"\$arg\" in
    --chrome)
      CLAWGOD_AUTO_CHROME=0
      break
      ;;
    -p|--print|--permission-mode|--input-format|--output-format)
      CLAWGOD_AUTO_CHROME=0
      ;;
  esac
done
case \"\${1:-}\" in
  -h|--help|-v|--version|version|update|upgrade|auth|login|logout|config|mcp|daemon|logs|attach|stop|kill|respawn|rm|doctor|install|uninstall|completion|migrate-installer|setup-token)
    CLAWGOD_AUTO_CHROME=0
    ;;
esac
if [ \"\$CLAWGOD_AUTO_CHROME\" = \"1\" ]; then
  exec \"\$BUN_BIN\" \"\$CLAWGOD_CLI\" --chrome \"\$@\"
fi
exec \"\$BUN_BIN\" \"\$CLAWGOD_CLI\" \"\$@\""


# Back up original claude (only once)
CLAUDE_ORIG="$CLAUDE_BIN.orig"
if { [ -e "$CLAUDE_ORIG" ] || [ -L "$CLAUDE_ORIG" ]; } \
  && { [ -e "$CLAUDE_BIN" ] || [ -L "$CLAUDE_BIN" ]; } \
  && ! is_clawgod_launcher "$CLAUDE_BIN"; then
  err "Claude launcher conflict at $CLAUDE_BIN; current command and $CLAUDE_ORIG were preserved."
  err "Move or remove the third-party current command, then rerun the installer."
  exit 1
fi
if [ -e "$CLAUDE_ORIG" ] || [ -L "$CLAUDE_ORIG" ]; then
  if has_clawgod_launcher_content "$CLAUDE_ORIG"; then
    rm -f "$CLAUDE_ORIG"
    warn "Removed installer-owned polluted backup ($CLAUDE_ORIG)"
  elif ! is_valid_claude_original "$CLAUDE_ORIG"; then
    err "Invalid original backup at $CLAUDE_ORIG; installation stopped without launcher changes."
    exit 1
  fi
fi
if [ ! -e "$CLAUDE_ORIG" ] && [ ! -L "$CLAUDE_ORIG" ] && ! is_clawgod_launcher "$CLAUDE_BIN"; then
  if [ -L "$CLAUDE_BIN" ]; then
    # Symlink (native install) — preserve target
    NATIVE_BIN="$(readlink "$CLAUDE_BIN")"
    ln -sf "$NATIVE_BIN" "$CLAUDE_ORIG"
    info "Original claude backed up → claude.orig (→ $NATIVE_BIN)"
  elif [ -f "$CLAUDE_BIN" ] && file "$CLAUDE_BIN" 2>/dev/null | grep -q "Mach-O\|ELF\|script"; then
    # Binary or script (pnpm/npm global install)
    cp "$CLAUDE_BIN" "$CLAUDE_ORIG"
    info "Original claude backed up → claude.orig"
  else
    # Try versions dir as fallback
    VERSIONS_DIR="$HOME/.local/share/claude/versions"
    if [ -d "$VERSIONS_DIR" ]; then
      NATIVE_BIN="$(ls -t "$VERSIONS_DIR"/* 2>/dev/null | while read f; do
        file "$f" 2>/dev/null | grep -q "Mach-O\|ELF" && echo "$f" && break
      done)" || true
      if [ -n "$NATIVE_BIN" ]; then
        ln -sf "$NATIVE_BIN" "$CLAUDE_ORIG"
        info "Original claude backed up → claude.orig (→ $NATIVE_BIN)"
      fi
    fi
  fi
fi

# Write launcher to the SAME directory where claude was found.
# CRITICAL: `echo > $f` follows symlinks — if $CLAUDE_BIN is a symlink
# (e.g. official ~/.local/bin/claude → ~/.local/share/claude/versions/X)
# we'd write our launcher into the real binary and destroy it. Always
# remove the existing entry first so we write a fresh regular file.
write_launcher() {
  local target="$1"
  local dir
  dir=$(dirname "$target")
  mkdir -p "$dir"
  rm -f "$target"
  printf '%s\n' "$LAUNCHER_CONTENT" > "$target"
  chmod +x "$target"
}

write_launcher "$CLAUDE_BIN"
info "Command 'claude' → patched ($CLAUDE_BIN)"

# Also install to ~/.local/bin if claude was elsewhere (ensures PATH consistency)
if [ "$CLAUDE_DIR" != "$BIN_DIR" ]; then
  write_launcher "$BIN_DIR/claude"
  dim "Also installed to $BIN_DIR/claude"
fi

# Always expose an unambiguous `clawgod` alias alongside the `claude` override.
# Useful when:
#  - Windows .exe overshadows our .cmd (clawgod has no .exe competitor)
#  - User wants explicit "patched" intent
#  - User restored claude.orig via uninstall but still wants the patched one
write_launcher "$BIN_DIR/clawgod"
info "Command 'clawgod' → patched ($BIN_DIR/clawgod)"

# Only the selected voice enhancement downloads the original, checksum-pinned addon.
if ! "$BUN_BIN" "$CLAWGOD_DIR/install-voice-asr.mjs" "$CLAWGOD_DIR"; then
  warn "Optional Cometix ASR setup failed; /voice will report a missing backend until repaired"
fi

# --- Ensure optional Claude plugins ---------------------------------

if ! CLAWGOD_BUN_BIN="$BUN_BIN" CLAWGOD_DIR="$CLAWGOD_DIR" \
  "$BUN_BIN" "$CLAWGOD_DIR/plugin-dependencies.mjs" ensure; then
  warn "Optional Claude plugin setup could not complete; ClawGod Plus core install will continue"
fi

install_claude_mem_compat_helper
if CLAWGOD_BUN_BIN="$BUN_BIN" CLAWGOD_CLAUDE_BIN="$CLAUDE_BIN" "$BUN_BIN" "$CLAWGOD_DIR/claude-mem-compat.cjs" install; then
  [ -f "$HOME/.claude-mem/clawgod-settings-backup.json" ] && info "claude-mem compatibility configured"
else
  warn "claude-mem compatibility setup failed; ClawGod Plus core install will continue"
fi

# --- Optional Claude Desktop enhancement ----------------------------

run_claude_desktop_enhancement() {
  [ "$(uname -s)" = Darwin ] || return 0
  local app="" candidate selected
  for candidate in "/Applications/Claude.app" "$HOME/Applications/Claude.app"; do
    if [ -f "$candidate/Contents/Resources/app.asar" ]; then
      app="$candidate"
      break
    fi
  done
  if [ -z "$app" ]; then
    dim "Claude Desktop not installed; skipping Desktop enhancement"
    return 0
  fi
  if ! selected=$("$BUN_BIN" -e '
    const {readFile}=await import("node:fs/promises");
    const {join,dirname}=await import("node:path");
    const {pathToFileURL}=await import("node:url");
    const root=process.argv[1];
    const {loadEnhancementManifest,readEnhancementConfig,resolveEnhancementSelection}=await import(pathToFileURL(join(root,"enhancement-config.mjs")).href);
    const manifest=loadEnhancementManifest(await readFile(join(root,"enhancement-manifest.json"),"utf8"));
    const stored=await readEnhancementConfig({homeDir:dirname(root),manifest});
    console.log(resolveEnhancementSelection({stored},manifest).enabled.includes("computer-use"));
  ' "$CLAWGOD_DIR"); then
    warn "Could not read Desktop enhancement selection; skipping"
    return 0
  fi
  if [ "$selected" != true ]; then
    dim "computer-use enhancement disabled; skipping Claude Desktop"
    return 0
  fi
  local helper="$CLAWGOD_DIR/restore-claude-3p-cu-browser.sh"
  local language="$CLAWGOD_DIR/desktop-language.mjs" catalogs="$CLAWGOD_DIR/desktop-zh-Hans.json"
  if ! cat > "$helper" << 'DESKTOP_ENHANCEMENT_EOF'
#!/bin/bash
# restore-claude-3p-cu-browser.sh
#
# 恢复 Claude Desktop 在公司 API（3p / custom-3p）模式下不可用的：
#   - In-App Computer Use（gate 4293378213 / 36693946）
#   - In-App Browser Use / 内置浏览器（gate 17519066 / 3990395613）
#   - 本地界面原生语言菜单的简体中文选项（内嵌词表，不强制切换语言）
#
# 原理：3p 模式且未配置 bootstrapUrl 时，GrowthBook 特性源为 static，只加载
# 最小静态表（不含 CU/浏览器 gate）。本脚本兼容旧静态表与 2.42304.0 的
# 规则注册表，补齐主进程与渲染器的 gate。纯本地代码恢复，不修改账号与网络。
#
# 完整流程（macOS）：
#   1. 从原始备份读取 app.asar，修补目标 JS chunk（正则定位，容忍混淆改名）
#   2. 以"字节拼接"方式重建 asar：仅替换目标 chunk，其余字节原样保留；
#      重算 chunk 的 SHA-256/分块哈希与后续文件偏移，并做全文件哈希自检
#   3. 计算新的 asar 头 JSON 哈希，等长替换包内所有 Info.plist 的
#      ElectronAsarIntegrity 值（Electron asar 完整性 fuse 校验的就是它）
#   4. 保留 entitlements/runtime 元数据后 ad-hoc 重签名，避免汉化副本丢失 JIT 权限
#   5. 重启 Claude；特性数仅供诊断，CU/浏览器仍需在界面中验证
#
# 依赖：python3、Bun、codesign（Xcode CLT）
# 注意：
#   - 应用自动更新会还原官方 asar，之后重新运行本脚本即可（幂等）
#   - 备份保存在 ~/Library/Application Support/Claude-3p/app.asar.orig-<版本>
#   - 回滚：bash restore-claude-3p-cu-browser.sh --restore
#   - 安装器调用 --install [Claude.app 路径]：运行中的应用跳过，完成后不启动应用

set -euo pipefail

APP="/Applications/Claude.app"
MODE="${1:-}"
case "$MODE" in
  --install|--restore) APP="${2:-$APP}" ;;
esac
ASAR="$APP/Contents/Resources/app.asar"
MAIN_PLIST="$APP/Contents/Info.plist"
USER_DATA_3P="$HOME/Library/Application Support/Claude-3p"

die() { echo "ERROR: $*" >&2; exit 1; }
if [[ "$MODE" == "--install" ]]; then
  [[ -f "$ASAR" ]] || { echo "==> Claude Desktop 未安装，跳过增强"; exit 0; }
  if pgrep -x Claude >/dev/null; then
    echo "==> Claude Desktop 正在运行，跳过增强；退出后重新运行 ClawGod 安装器"
    exit 0
  fi
fi
[[ -f "$ASAR" ]] || die "未找到 $ASAR"
command -v python3 >/dev/null || die "需要 python3"
command -v codesign >/dev/null || die "需要 codesign（安装 Xcode Command Line Tools）"

VERSION=$(/usr/libexec/PlistBuddy -c 'Print :CFBundleShortVersionString' "$MAIN_PLIST" 2>/dev/null || echo unknown)
BACKUP="$USER_DATA_3P/app.asar.orig-$VERSION"
LANGUAGE_HELPER="$(dirname "${BASH_SOURCE[0]}")/desktop-language.mjs"
LANGUAGE_BACKUP="$USER_DATA_3P/desktop-language.orig-$VERSION"

quit_claude() {
  if [[ "$MODE" == "--install" ]]; then
    if pgrep -x Claude >/dev/null; then
      echo "==> Claude Desktop 已启动，跳过增强；退出后重新运行 ClawGod 安装器"
      exit 0
    fi
    return 0
  fi
  osascript -e 'tell application "Claude" to quit' >/dev/null 2>&1 || true
  for _ in $(seq 1 20); do pgrep -x Claude >/dev/null || break; sleep 0.5; done
}


# 读取 Info.plist 当前的 asar 头哈希（Electron 的完整性校验值）
get_plist_hash() {
  /usr/libexec/PlistBuddy -c 'Print :ElectronAsarIntegrity:Resources/app.asar:hash' "$MAIN_PLIST" 2>/dev/null || true
}

# ---------- --restore ----------
if [[ "${1:-}" == "--restore" ]]; then
  [[ -f "$BACKUP" ]] || die "未找到备份 $BACKUP"
  quit_claude
  if [[ -f "$LANGUAGE_BACKUP/manifest.json" ]]; then
    [[ -f "$LANGUAGE_HELPER" ]] || die "缺少中文资源回滚助手 $LANGUAGE_HELPER"
    "${CLAWGOD_BUN_BIN:-bun}" "$LANGUAGE_HELPER" restore "$APP" "$LANGUAGE_BACKUP" || die "中文资源回滚失败；保留备份以便重试"
  fi
  python3 - "$BACKUP" "$ASAR" "$APP/Contents" "$(get_plist_hash)" <<'PYEOF'
import sys, json, struct, hashlib, os
src, asar_path, contents, old = sys.argv[1], sys.argv[2], sys.argv[3], (sys.argv[4] or "")
raw = open(src, "rb").read()
jl = struct.unpack("<I", raw[12:16])[0]
restore_hash = hashlib.sha256(raw[16:16+jl]).hexdigest()
open(asar_path, "wb").write(raw); os.chmod(asar_path, 0o644)
n = 0
if old and old != restore_hash:
    for root, dirs, files in os.walk(contents):
        for fn in files:
            if fn == "Info.plist":
                p = os.path.join(root, fn)
                try: t = open(p, "rb").read()
                except OSError: continue
                if old.encode() in t:
                    open(p, "wb").write(t.replace(old.encode(), restore_hash.encode())); n += 1
print("plist hash restored in %d files (old=%s new=%s)" % (n, old[:16], restore_hash[:16]))
PYEOF
  codesign --force --deep --preserve-metadata=entitlements,flags,runtime --sign - "$APP" >/dev/null 2>&1 || die "codesign 失败；回滚备份保留以便重试"
  open "$APP"
  echo "✅ 已回滚到原始 asar 并重启 Claude"
  exit 0
fi

# ---------- 打补丁 ----------
command -v "${CLAWGOD_BUN_BIN:-bun}" >/dev/null || die "需要 Bun（用于写入前的 JavaScript 语法检查）"
echo "==> Claude Desktop $VERSION"
mkdir -p "$USER_DATA_3P"
if [[ ! -f "$BACKUP" ]]; then
  quit_claude
  cp "$ASAR" "$BACKUP"
  echo "==> 已创建备份: $BACKUP"
fi

echo "==> 准备修补 asar"
quit_claude

RESULT=$(python3 - "$BACKUP" "$ASAR" "$APP/Contents" "$(get_plist_hash)" <<'PYEOF'
import sys, json, struct, hashlib, re, os, subprocess

backup_path, asar_path, contents, old_hash_arg = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
raw = open(backup_path, "rb").read()          # 永远从原始备份构建（幂等）
hbl = struct.unpack("<I", raw[4:8])[0]
jl  = struct.unpack("<I", raw[12:16])[0]
hdr = json.loads(raw[16:16+jl].decode())
ds  = 8 + hbl

def walk(node, path=""):
    if "files" in node:
        for n, c in node["files"].items():
            yield from walk(c, path + "/" + n)
    elif "offset" in node:
        yield path, node

# 定位含 3p 静态特性表的 chunk（不写死文件名，跨版本可定位）
PAT_BROWSER  = re.compile(r"\{17519066:([A-Za-z_$][\w$]*),3990395613:\1\}")
PAT_SELECTOR = re.compile(r"function ([A-Za-z_$][\w$]*)\(([A-Za-z_$][\w$]*)\)\{return \2\.builtinBrowserEnabled\?([A-Za-z_$][\w$]*):([A-Za-z_$][\w$]*)\}")
PAT_BROWSER_RULES = re.compile(r'(17519066|3990395613):\{rule:"forcedFor",group:"builtinBrowser",value:!0\}')
PAT_NET_RULE = re.compile(r'4112513247:\{rule:"when",condition:"builtinBrowserEnabled",value:!0\}')
# 渲染层 bootstrap 的 growthbook 默认表（nEt）：内置浏览器 gate 4112513247 挂在
# 托管配置 builtinBrowserEnabled 下；"chicago"(CU) 的 hash key 745998442 缺失。
# （hash 算法 = 渲染层 R()：Java 32-bit hashCode 的十进制字符串）
PAT_NET = re.compile(r"\.\.\.[A-Za-z_$][\w$]*\.builtinBrowserEnabled&&\{4112513247:([A-Za-z_$][\w$]*)\(!0\)\}")
# buildConfig 暴露给渲染器的 builtinBrowserEnabled 字段也来自托管配置，恒真化
PAT_BUILD = re.compile(r"builtinBrowserEnabled:this\.builtinBrowserEnabled\(\)")
# current_user_access 里 dramatic_shrimp(Cowork 组织开关，含浏览器面板) 为
# void 0 时会被剔除 → 渲染层判“不可用”→ 浏览器按钮/设置组全部隐藏
PAT_ACCESS = re.compile(r'dramatic_shrimp:void 0')
# isCoworkBrowserAvailable：原逻辑依赖 PreviewPolicy 初始化时序（未初始化即
# fail-closed），窗口创建时的状态快照会固化为 unsupported → 恒真化
PAT_AJ = re.compile(r'function ([A-Za-z_$][\w$]*)\(\)\{return [A-Za-z_$][\w$]*\(\)\?[A-Za-z_$][\w$]*\("3990395613"\):!1\}')

tp = te = text = None
for p, e in walk(hdr):
    if not p.endswith((".js", ".cjs")):
        continue
    off, size = int(e["offset"]), e["size"]
    c = raw[ds+off : ds+off+size]
    if b"17519066" in c and b"builtinBrowserEnabled" in c:
        tp, te, text = p, e, c.decode("utf-8", "surrogateescape")
        break

if text is None:
    print("RESULT=TARGET_NOT_FOUND"); sys.exit(2)
# 已打补丁 = 静态表中存在 4293378213 映射条目（原代码只有带引号的调用点字面量）
if re.search(r"[,{]4293378213:[A-Za-z_$]", text):
    print("RESULT=ALREADY_PATCHED"); sys.exit(0)
legacy = bool(PAT_BROWSER.search(text))
patterns = [("browser", PAT_BROWSER, 1), ("selector", PAT_SELECTOR, 1), ("renderer", PAT_NET, 1)] if legacy else [
    ("browser rules", PAT_BROWSER_RULES, 2), ("renderer rule", PAT_NET_RULE, 1)]
patterns += [("Cowork access", PAT_ACCESS, 1), ("browser availability", PAT_AJ, 1)]
missing = ["%s: expected %d, found %d" % (name, count, len(pattern.findall(text)))
           for name, pattern, count in patterns if len(pattern.findall(text)) != count]
if not PAT_BUILD.search(text):
    missing.append("builtinBrowserEnabled config")
if missing:
    print("RESULT=PATTERN_MISMATCH (%s)" % "; ".join(missing)); sys.exit(2)

off0, size0 = int(te["offset"]), te["size"]
abs0 = ds + off0
# 保留上游未列出的 CU 子开关默认值。
cu_cfg = ('{"enabled":true,"batchOnly":false,"teachModeEnabled":true,'
          '"clipboardPasteMultiline":true,"coordinateMode":"pixels",'
          '"dispatchCuGrantTtlMs":1800000,"hideBeforeAction":true,'
          '"mouseAnimation":true,"pixelValidation":false,"screenshotFilter":true}')
def sub_browser(mm):
    g = mm.group(1)
    # CU 配置 gate 1291166712（chicago_config）：enabled=true 是设置入口与
    # 会话内 CU 的总开关；batchOnly=false 保持交互式控制而非仅批量截图
    cu_entry = ('1291166712:{value:%s,on:true,off:false,source:"force",'
                'experiment:null,experimentResult:null}' % cu_cfg)
    return "{17519066:%s,3990395613:%s,4293378213:%s,36693946:%s,%s}" % (g, g, g, g, cu_entry)
if legacy:
    text = PAT_BROWSER.sub(sub_browser, text, count=1)
    text = PAT_SELECTOR.sub(lambda m: "function %s(%s){return %s}" % (m.group(1), m.group(2), m.group(3)), text, count=1)
    g3 = PAT_NET.search(text).group(1)
    text = PAT_NET.sub(
        "...!0&&{4112513247:%s(!0),745998442:%s(!0),709117870:%s(!1)}" % (g3, g3, g3),
        text, count=1)
else:
    def sub_browser_rule(m):
        entry = '%s:{rule:"forced",value:!0}' % m.group(1)
        if m.group(1) == "3990395613":
            entry += (',4293378213:{rule:"forced",value:!0},36693946:{rule:"forced",value:!0},'
                      '1291166712:{rule:"forced",value:%s}' % cu_cfg)
        return entry
    text = PAT_BROWSER_RULES.sub(sub_browser_rule, text)
    text = PAT_NET_RULE.sub(
        '4112513247:{rule:"always",value:!0},745998442:{rule:"always",value:!0},709117870:{rule:"always",value:!1}',
        text, count=1)
# 补丁 4：rendererConfig 的 builtinBrowserEnabled 字段恒真
text = PAT_BUILD.sub("builtinBrowserEnabled:!0", text)
# 补丁 5：Cowork 组织开关（浏览器面板）在 current_user_access 中置为 available
text = PAT_ACCESS.sub('dramatic_shrimp:"available"', text, count=1)
# 补丁 6：isCoworkBrowserAvailable 恒真（绕过 PreviewPolicy 初始化时序的 fail-closed）
text = PAT_AJ.sub(lambda m: "function %s(){return!0}" % m.group(1), text, count=1)
new_content = text.encode("utf-8", "surrogateescape")
delta = len(new_content) - size0

def rehash(e, c):
    e["size"] = len(c)
    bs = e["integrity"].get("blockSize", 4194304)
    blocks = [c[i:i+bs] for i in range(0, len(c), bs)] or [b""]
    e["integrity"]["hash"] = hashlib.sha256(c).hexdigest()
    e["integrity"]["blocks"] = [hashlib.sha256(b).hexdigest() for b in blocks]

rehash(te, new_content)
for p, e in walk(hdr):
    if e is not te and int(e["offset"]) >= off0:
        e["offset"] = str(int(e["offset"]) + delta)

new_json = json.dumps(hdr, ensure_ascii=False, separators=(",", ":")).encode()
pad = (4 - len(new_json) % 4) % 4
payload = struct.pack("<I", len(new_json)) + new_json + b"\x00" * pad
header_buf = struct.pack("<I", len(payload)) + payload
prefix = struct.pack("<I", 4) + struct.pack("<I", len(header_buf)) + header_buf

# 拼接：原字节保留，仅替换目标 chunk 段
out = prefix + raw[ds:abs0] + new_content + raw[abs0+size0:]

# 全文件哈希自检（任何偏移/顺序错误在此拦截）
new_ds = 8 + len(header_buf)
bad = 0
for p, e in walk(hdr):
    o, s = int(e["offset"]), e["size"]
    if hashlib.sha256(out[new_ds+o : new_ds+o+s]).hexdigest() != e["integrity"]["hash"]:
        bad += 1
if bad:
    print("RESULT=VERIFY_FAILED (%d files)" % bad); sys.exit(3)

# 写入前完成语法与 plist 检查，失败时保留当前可启动的应用。
syntax = subprocess.run([os.environ.get("CLAWGOD_BUN_BIN", "bun"), "-e", 'new Bun.Transpiler({loader:"js"}).transformSync(await Bun.stdin.text());'],
                        input=new_content, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
if syntax.returncode:
    sys.stderr.write(syntax.stderr.decode("utf-8", "replace"))
    print("RESULT=SYNTAX_CHECK_FAILED"); sys.exit(3)
new_hash = hashlib.sha256(new_json).hexdigest()
old_hash = old_hash_arg.strip()
if not re.fullmatch(r"[0-9a-fA-F]{64}", old_hash):
    print("RESULT=PLIST_HASH_NOT_FOUND"); sys.exit(4)
plists = {}
for root, dirs, files in os.walk(contents):
    for fn in files:
        if fn == "Info.plist":
            p = os.path.join(root, fn)
            try: t = open(p, "rb").read()
            except OSError: continue
            if old_hash.encode() in t:
                plists[p] = t.replace(old_hash.encode(), new_hash.encode())
if os.path.join(contents, "Info.plist") not in plists:
    print("RESULT=PLIST_HASH_NOT_FOUND (Info.plist does not contain the current hash)"); sys.exit(4)
open(asar_path, "wb").write(out)
os.chmod(asar_path, 0o644)
for p, data in plists.items():
    open(p, "wb").write(data)
print("RESULT=PATCH_OK")
print("INFO_PLISTS=%d" % len(plists))
print("OLD_HASH=" + old_hash)
print("NEW_HASH=" + new_hash)
print("DELTA=%d" % delta)
PYEOF
) || { printf '%s\n' "$RESULT" >&2; die "asar 补丁失败"; }

STATUS=$(echo "$RESULT" | grep -o "RESULT=[A-Z_]*" | head -1 | cut -d= -f2)
case "$STATUS" in
  PATCH_OK)
    echo "$RESULT" | grep -v "^RESULT=" || true
    ;;
  ALREADY_PATCHED)
    echo "==> 已打过补丁，无需修改"
    ;;
  *) die "补丁未生效: $STATUS（应用版本可能变化，需重新分析）" ;;
esac

if [[ -f "$LANGUAGE_HELPER" ]]; then
  if ! "${CLAWGOD_BUN_BIN:-bun}" "$LANGUAGE_HELPER" install "$APP" "$LANGUAGE_BACKUP"; then
    echo "⚠️ 简体中文选项增强未完成；CU/浏览器补丁继续生效，语言备份保留以便重试"
  fi
else
  echo "==> 未找到中文资源助手，跳过语言选项增强"
fi

echo "==> 保留 JIT 等签名权限并 ad-hoc 重签名"
codesign --force --deep --preserve-metadata=entitlements,flags,runtime --sign - "$APP" >/dev/null 2>&1 || die "codesign 失败"

if [[ "$MODE" == "--install" ]]; then
  echo "✅ Claude Desktop CU/浏览器补丁已写入，下次启动应用时生效；实际工具仍需在会话中验证"
  echo "   回滚: bash \"$0\" --restore \"$APP\""
  exit 0
fi

echo "==> 重启 Claude"
open "$APP"
sleep 12
if pgrep -x Claude >/dev/null; then
  FEAT=$(grep "loaded .* features" "$HOME/Library/Logs/Claude-3p/main.log" 2>/dev/null | tail -1 | sed -E 's/.*loaded ([0-9]+) features.*/\1/' || true)
  echo "✅ 补丁完成，Claude 已重启（growthbook 特性数: ${FEAT:-未知}，仅供诊断）"
  echo "   请在界面确认 CU/浏览器入口及实际会话工具是否可用"
  echo "   回滚: bash $0 --restore；应用更新后重新运行本脚本即可"
else
  echo "⚠️ Claude 未启动，崩溃报告见 ~/Library/Logs/DiagnosticReports/"
  echo "   可回滚: bash $0 --restore"
fi
DESKTOP_ENHANCEMENT_EOF
  then
    warn "Could not install optional Claude Desktop helper; ClawGod Plus core install will continue"
    return 0
  fi
  if ! cat > "$language" << 'DESKTOP_LANGUAGE_EOF'
#!/usr/bin/env bun
import { createHash, randomUUID } from 'node:crypto';
import { existsSync, lstatSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, renameSync, rmSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';

const ionPath = 'Contents/Resources/ion-dist';
const oldLocales = '["en-US","de-DE","fr-FR","ko-KR","ja-JP","es-419","es-ES","it-IT","hi-IN","pt-BR","id-ID"]';
const chineseLocales = oldLocales.slice(0, -1) + ',"zh-Hans"]';
const hash = bytes => bytes === null ? null : createHash('sha256').update(bytes).digest('hex');
function status(path) {
  try { return lstatSync(path); } catch (error) { if (error.code === 'ENOENT') return null; throw error; }
}
function directory(path) {
  const info = status(path);
  if (!info?.isDirectory() || info.isSymbolicLink()) throw new Error(`Unsafe Desktop directory or symlink: ${path}`);
}
function safePath(root, name) {
  if (typeof name !== 'string' || isAbsolute(name) || name.includes('\\') || name.split('/').some(part => !part || part === '.' || part === '..')) throw new Error('Unsafe Desktop backup path');
  directory(root);
  let path = root;
  for (const part of name.split('/')) {
    path = join(path, part);
    if (status(path)?.isSymbolicLink()) throw new Error(`Refusing Desktop symlink: ${path}`);
  }
  return path;
}
function bytes(path) {
  const info = status(path);
  if (!info) return null;
  if (!info.isFile() || info.isSymbolicLink()) throw new Error(`Unsafe Desktop file: ${path}`);
  return readFileSync(path);
}
function catalog(value, allowEmpty = false) {
  if (!value || typeof value !== 'object' || Array.isArray(value) || (!allowEmpty && !Object.keys(value).length)
    || Object.values(value).some(text => typeof text !== 'string')) throw new Error('Invalid Desktop Chinese catalog');
}
function atomicWrite(path, data) {
  if (data === null) { if (existsSync(path)) unlinkSync(path); return; }
  mkdirSync(dirname(path), { recursive: true });
  const temporary = `${path}.clawgod-${randomUUID()}.tmp`;
  try {
    writeFileSync(temporary, data, { flag: 'wx', mode: 0o644 });
    renameSync(temporary, path);
  } finally { if (existsSync(temporary)) unlinkSync(temporary); }
}
function apply(changes) {
  const written = [];
  try {
    for (const change of changes) { atomicWrite(change.path, change.after); written.push(change); }
  } catch (error) {
    const errors = [error];
    for (const change of written.reverse()) {
      try { atomicWrite(change.path, change.before); } catch (rollback) { errors.push(rollback); }
    }
    throw new AggregateError(errors, 'Desktop language write failed; attempted rollback');
  }
}
function readBackup(app, backup) {
  directory(backup);
  const value = JSON.parse(readFileSync(safePath(backup, 'manifest.json'), 'utf8'));
  if (value?.schemaVersion !== 1 || value.appPath !== app || !Array.isArray(value.files) || !value.files.length) throw new Error('Invalid Desktop language backup manifest');
  const seen = new Set();
  for (const file of value.files) {
    if (!file || typeof file.path !== 'string' || !file.path.startsWith(`${ionPath}/`) || seen.has(file.path)
      || (file.before !== null && !/^[a-f0-9]{64}$/.test(file.before)) || !/^[a-f0-9]{64}$/.test(file.after)) throw new Error('Invalid Desktop language backup record');
    safePath(app, file.path); safePath(backup, `files/${file.path}`); seen.add(file.path);
  }
  return value;
}
function originalBytes(backup, file) {
  const value = bytes(safePath(backup, `files/${file.path}`));
  if (hash(value) !== file.before) throw new Error('Desktop language backup content changed');
  return value;
}
function owned(current, file) {
  if (hash(current) !== file.after && hash(current) !== file.before) throw new Error(`Desktop language ownership changed; user-modified file preserved: ${file.path}`);
}

export function installDesktopChinese(app, backup, catalogs) {
  app = resolve(app); backup = resolve(backup);
  if (!status(app)) return 'Claude Desktop not installed; Chinese language skipped';
  directory(app);
  catalogs ??= JSON.parse(readFileSync(new URL('./desktop-zh-Hans.json', import.meta.url), 'utf8'));
  if (catalogs?.schemaVersion !== 1 || catalogs.locale !== 'zh-Hans') throw new Error('Invalid Desktop Chinese catalog schema');
  catalog(catalogs.base); catalog(catalogs.dynamic, true);
  const ion = safePath(app, ionPath), assets = safePath(app, `${ionPath}/assets`);
  directory(ion); directory(assets);
  const changes = [];
  const plan = (path, after) => {
    const before = bytes(path);
    if (before === null || !before.equals(after)) changes.push({ path, before, after });
  };
  let count = 0;
  for (const name of readdirSync(assets, { recursive: true })) {
    if (!name.endsWith('.js')) continue;
    const path = safePath(app, `${ionPath}/assets/${name.split(sep).join('/')}`);
    const source = bytes(path).toString('utf8');
    count += source.split(oldLocales).length - 1 + source.split(chineseLocales).length - 1;
    if (!source.includes(oldLocales)) continue;
    const patched = source.replaceAll(oldLocales, chineseLocales);
    new Bun.Transpiler({ loader: 'js' }).transformSync(patched);
    plan(path, Buffer.from(patched));
  }
  if (count !== 2) throw new Error(`Desktop locale lists changed: expected 2, found ${count}`);
  for (const [name, messages] of [['i18n/zh-Hans.json', catalogs.base], ['i18n/dynamic/zh-Hans.json', catalogs.dynamic]]) {
    const path = safePath(app, `${ionPath}/${name}`), current = bytes(path);
    if (current === null) plan(path, Buffer.from(JSON.stringify(messages)));
    else catalog(JSON.parse(current.toString()), name.includes('dynamic/'));
  }
  const index = safePath(app, `${ionPath}/index.html`);
  let html = bytes(index).toString('utf8');
  const meta = html.match(/<meta\b[^>]*name=["']i18n-catalogs["'][^>]*>/g);
  if (meta) {
    if (meta.length !== 1 || !/data-i18n-catalogs="[^"]*"/.test(meta[0])) throw new Error('Desktop catalog manifest format changed');
    const patched = meta[0].replace(/data-i18n-catalogs="([^"]*)"/, (match, value) => value.split(',').some(entry => entry.startsWith('zh-Hans:')) ? match : `data-i18n-catalogs="${value}${value ? ',' : ''}zh-Hans:1.1.1"`);
    html = html.replace(meta[0], patched);
  } else {
    if (html.split('</head>').length !== 2) throw new Error('Desktop HTML format changed');
    const locales = new Set(readdirSync(safePath(app, `${ionPath}/i18n`)).filter(name => /^[a-z]{2,3}(?:-[A-Za-z0-9]{2,8})*\.json$/.test(name)).map(name => name.slice(0, -5)));
    locales.add('zh-Hans');
    html = html.replace('</head>', `<meta name="i18n-catalogs" data-i18n-catalogs="${[...locales].sort().map(locale => `${locale}:1.1.1`).join(',')}"></head>`);
  }
  plan(index, Buffer.from(html));
  if (!changes.length) return 'Claude Desktop already has the native Simplified Chinese option';

  if (status(backup)) {
    const saved = readBackup(app, backup);
    for (const file of saved.files) { originalBytes(backup, file); owned(bytes(safePath(app, file.path)), file); }
    for (const change of changes) {
      const file = saved.files.find(file => file.path === relative(app, change.path).split(sep).join('/'));
      if (!file || file.after !== hash(change.after)) throw new Error('Desktop language backup patch shape changed');
    }
  } else {
    mkdirSync(dirname(backup), { recursive: true, mode: 0o700 });
    const staging = mkdtempSync(`${backup}.staging-`);
    try {
      const files = changes.map(change => {
        const name = relative(app, change.path).split(sep).join('/');
        if (change.before !== null) {
          const path = safePath(staging, `files/${name}`);
          mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, change.before, { flag: 'wx', mode: 0o600 });
        }
        return { path: name, before: hash(change.before), after: hash(change.after) };
      });
      writeFileSync(join(staging, 'manifest.json'), JSON.stringify({ schemaVersion: 1, appPath: app, files }) + '\n', { flag: 'wx', mode: 0o600 });
      renameSync(staging, backup);
    } finally { if (existsSync(staging)) rmSync(staging, { recursive: true, force: true }); }
  }
  apply(changes);
  return 'Claude Desktop native language menu now includes Simplified Chinese (current language preserved)';
}

export function restoreDesktopChinese(app, backup) {
  app = resolve(app); backup = resolve(backup);
  if (!status(backup)) return 'No managed Desktop language backup; existing language resources preserved';
  const saved = readBackup(app, backup);
  const changes = saved.files.map(file => {
    const path = safePath(app, file.path), before = bytes(path);
    owned(before, file);
    return { path, before, after: originalBytes(backup, file) };
  }).filter(change => hash(change.before) !== hash(change.after));
  apply(changes);
  return 'Managed Desktop language resources restored; backups retained';
}

if (import.meta.main) {
  try {
    const [command, app, backup] = process.argv.slice(2);
    if (!app || !backup || !['install', 'restore'].includes(command)) throw new Error('usage: desktop-language.mjs install|restore <Claude.app> <backup-directory>');
    console.log(command === 'install' ? installDesktopChinese(app, backup) : restoreDesktopChinese(app, backup));
  } catch (error) { console.error(error.message); process.exitCode = 1; }
}
DESKTOP_LANGUAGE_EOF
